if(['R07','A24'].includes(screen))return <><Head/><Card className="form"><div className="cardhead"><Pill tone="warning">Important</Pill><small>24 Oct 2026 · 10 AM–1 PM IST</small></div><h1>Water tank cleaning</h1><p style={{margin:'24px 0'}}>Water supply will pause from 10:00 AM to 1:00 PM on 24 October while the common tank is cleaned. Please store enough water for your household.</p><Banner>{screen==='R07'?'Opened · marked as read. Dismissing a banner is a separate local action.':'Scheduled announcement · community timezone Asia/Kolkata.'}</Banner>{screen==='A24'?<Btn danger disabled={data.announcementEnded} onClick={()=>confirm('End announcement?','It will stop being active for residents. This does not delete its history.',()=>{D({announcementEnded:true});notify('Announcement ended.');},'End announcement')}>{data.announcementEnded?'Ended':'End announcement'}</Btn>:<Btn secondary onClick={()=>go('R06')}>Back to updates</Btn>}</Card></>;
if(screen==='A23')return <><Head subtitle="Schedule in community timezone · Asia/Kolkata (IST)."/><AppForm id={screen} back={()=>go('A22')} button="Review announcement" onSubmit={v=>{if(v.Starts>=v.Ends)return 'End time must be after the start time.';reviewSubmit(v,()=>{D({announcement:true,announcementEnded:false});go('A24');notify('Announcement created in this prototype.')},'Announcement preview')}}><label className="check"><input type="checkbox" defaultChecked/>Mark as important</label><label className="check"><input type="checkbox" defaultChecked/>Show a resident banner</label></AppForm></>;
