if(screen==='A29'||screen==='A30')return <><Head subtitle={screen==='A29'?'Your organization and access context.':'All community destinations.'}/><div className="grid"><Card>{(screen==='A30'?['L01','C04','A21','A22','A25','A28','A03','A29']:['A12','S04','P01']).map(id=><button className="row full" key={id} onClick={()=>go(id)}><strong>{names[id]}</strong><CaretRight size={19}/></button>)}{screen==='A29'&&<><div className="details"><div><small>Organization</small><strong>Lakeview Residency</strong></div><div><small>Currency</small><strong>INR · ₹</strong></div><div><small>Apartment ID</small><strong>APT-1042</strong></div><div><small>Access</small><strong>Ravi Kumar · Admin</strong></div></div><p className="terms">Organization, team and payment integration editing are unavailable. Change billing in Billing.</p></>}</Card><Card><Field label="Language" type="select" options={['English','తెలుగు']} value={data.language} onChange={v=>D({language:v})}/><button className="row full" onClick={()=>go('S04')}><span>Switch workspace</span><Buildings size={20}/></button><button className="row full" onClick={()=>go('P01')}><span>Add to Home Screen</span><DeviceMobile size={20}/></button><button className="row full" onClick={()=>go('S01')}><span>Sign out</span><SignOut size={20}/></button></Card></div></>;
