if(screen==='C02'||screen==='C06')return <><Head/><AppForm key={screen} id={screen} back={()=>go(screen==='C02'?'C01':'C04')} button={screen==='C02'?'Submit complaint':'Create task'} onSubmit={v=>{if(screen==='C02'&&v.Subject.trim().length<4)return 'Add a descriptive subject.';action(()=>{D(screen==='C02'?{complaintCreated:true,complaintStatus:'Open'}:{taskCreated:true});go(screen==='C02'?'C03':'C07')},screen==='C02'?'Complaint CMP-1024 created.':'Maintenance task created.')}}>{screen==='C02'&&<><label className="field"><span>Photos (optional)</span><input type="file" accept="image/*" multiple onChange={e=>setUpload(Array.from(e.target.files).map(f=>f.name).join(', '))}/><small>{upload||'Select photos to preview attachment names. Upload storage is not connected.'}</small></label><div className="privacy"><Lock size={16}/>Only you and authorized apartment admins can view this complaint.</div></>}</AppForm></>;
if(screen==='C07')return <><Head/><Card className="form"><div className="cardhead"><h2>Inspect common water pump</h2><Pill tone={data.taskDone?'success':'warning'}>{data.taskDone?'Completed':'Due 25 Oct'}</Pill></div><div className="details"><div><small>Location</small><strong>Block A · Pump room</strong></div><div><small>Owner</small><strong>Ravi Kumar</strong></div></div><p>Check pipe connections and test the pump.</p><label className="check"><input type="checkbox"/>Inspect connections</label><label className="check"><input type="checkbox"/>Test pump operation</label><Field label="Completion note" type="textarea" value={reply} onChange={setReply}/><div className="actions"><Btn disabled={data.taskDone||blocked} onClick={()=>{if(!reply.trim())return notify('Add a completion note.');action(()=>D({taskDone:true}),'Task completed.')}}>Mark completed</Btn><Btn secondary onClick={()=>go('L06')}>Record related expense</Btn></div><p className="terms">Completing a task does not post an expense or payment.</p></Card></>;
const admin=screen==='C05';return <><Head subtitle="CMP-1024 · Created 21 October 2026"/><div className={'grid '+(admin?'wide':'')}><Card><div className="cardhead"><Pill tone={data.complaintStatus==='Resolved'?'success':'warning'}>{data.complaintStatus}</Pill><small>Plumbing · A-0201</small></div><h2>Water leakage in bathroom</h2><p className="terms">Ananya Rao · Private complaint</p><div className="complaintphotos"><img src="assets/leak-photo.png" alt="Water damage on the bathroom ceiling"/><img src="assets/bathroom-photo.png" alt="Bathroom where the leak was reported"/></div>{thread(admin)}{!admin&&data.complaintStatus==='Resolved'&&<div className="actions"><Btn onClick={()=>D({complaintStatus:'Closed'})}>Accept resolution</Btn><Btn secondary onClick={()=>{if(!reply.trim())return notify('Write a reason in the reply field before reopening.');D({complaintStatus:'Open'});sendReply()}}>Reopen with reason</Btn></div>}</Card>{admin&&<Card><h2>Manage request</h2><Field label="Priority" type="select" options={['Normal','Urgent']} value={data.priority} onChange={v=>D({priority:v})}/><Field label="Assigned admin" type="select" options={['Ravi Kumar','Unassigned']} value={data.owner} onChange={v=>D({owner:v})}/><Field label="Status" type="select" options={['Open','In progress','Awaiting resident','Resolved','Closed']} value={data.complaintStatus} onChange={v=>{if(v==='Resolved'&&!reply.trim())return notify('Add a visible resolution reply before resolving.');action(()=>D({complaintStatus:v}),'Status updated.')}}/><Banner>Internal notes stay private. Residents see replies and resolution notes.</Banner><Btn secondary onClick={()=>go('L06')}>Record related expense</Btn></Card>}</div></>;
