if(screen==='A04'||screen==='A08'||screen==='A10')return <><Head subtitle={screen==='A10'?'Move-out and replacement are separate steps. Former dues stay with the former resident.':undefined}/><AppForm key={screen} id={screen} back={()=>go('A07')} button={screen==='A04'?'Continue to draft flats':screen==='A08'?'Review invitation':'Review move-out'} onSubmit={v=>{if(screen==='A04'){if(+v.Floors<1||+v.Floors>200)return 'Floors must be between 1 and 200.';go('A05');return}if(screen==='A10'&&v['Replacement starts']<=v['Move-out date'])return 'Replacement must start after move-out.';reviewSubmit(v,()=>{if(screen==='A10'){D({moved:true});notify('Move-out saved. Review the replacement invitation separately.');go('A08')}else{D({invited:true});go('A09')}},screen==='A10'?'Review move-out':'Review invitation')}}>{screen==='A10'&&<Banner tone="warning">Pending reports must be verified before settlement. An invitation failure must not undo a saved move-out.</Banner>}</AppForm></>;
