if(screen==='A09')return <><Head/><Card><Records columns={['Resident','Flat','Starts','Status','Actions']} rows={[[<><strong>Meera Iyer</strong><small>meera@example.test</small></>,'A-0202','1 Nov 2026',<Pill>{data.invitation}</Pill>,<div className="actions"><button className="link" onClick={()=>notify('Invitation resent in this simulation. Seven-day expiry renewed.')}>Resend</button><button className="link" onClick={()=>confirm('Revoke invitation?','The invited resident will no longer be able to accept.',()=>D({invitation:'Revoked'}),'Revoke')}>Revoke</button></div>]]}/><p className="terms">Invitations expire after seven days. A future start is scheduled occupancy.</p></Card></>;
if(screen==='A11')return <><Head/><Card className="form"><h2>Ananya Rao · Former resident · A-0201</h2><div className="row"><span>Outstanding</span><strong>{cash(data.settled?0:due)}</strong></div><Banner tone="warning">Settlement records real money received. It is not a waiver. A replacement resident does not inherit these dues.</Banner><Btn disabled={pending>0||data.settled} onClick={()=>confirm('Confirm former resident settlement','Record money actually received outside this app?',()=>D({settled:true}),'Confirm received')}>Confirm settlement</Btn>{pending>0&&<p className="terms">Verify the pending payment report first.</p>}</Card></>;
return <><Head subtitle="Occupancy, invitations and resident account context."><Btn onClick={()=>go('A08')}><Plus size={17}/>Invite resident</Btn></Head><div className="actions" style={{marginBottom:20}}><Btn secondary onClick={()=>go('A03')}>Manage blocks</Btn><Btn secondary onClick={()=>go('A09')}>Invitations</Btn></div><FilterBar placeholder="Search resident or flat…" statuses={['All','Occupied','Vacant','Scheduled']}/>{query&&!('ananya rao a-0201'.includes(query.toLowerCase()))?<NoMatch/>:<Card><Records columns={['Flat / resident','Occupancy','Dues','Actions']} rows={[[<><strong>A-0201</strong><small>{data.moved?'Former · Ananya Rao':'Ananya Rao'}</small></>,<Pill>{data.moved?'Vacant':'Occupied'}</Pill>,cash(due),<div className="actions"><button className="link" onClick={()=>go('A10')}>Move-out</button><button className="link" onClick={()=>go('L03')}>Ledger</button></div>],...['A-0202','A-0203','A-0204'].map(f=>[<strong>{f}</strong>,<Pill>Vacant</Pill>,'—',<button className="link" onClick={()=>go('A08')}>Invite resident</button>])]}/><div className="pagination"><small>1–4 of 4 · 20 flats per page</small><span>Page 1</span></div></Card>}</>;
