if(screen==='A16')return <><Head subtitle="October 2026 · Review inputs before generating invoices."/><AppForm id={screen} extraFields={template==='Metered water'?[['Opening reading (kL)','number','120'],['Closing reading (kL)','number','134']]:[]} back={()=>go('A12')} button="Generate preview" onSubmit={v=>{if(v['Closing reading (kL)']&&+v['Closing reading (kL)']<+v['Opening reading (kL)'])return 'Closing reading cannot be below opening.';if(+v['Extra charge (₹)']&& !v['Extra charge reason'].trim())return 'Explain the extra charge.';go('A17')}}><p className="terms">A-0201 · Ananya Rao</p><label className="check"><input type="checkbox"/>Exclude this flat from this billing run</label></AppForm></>;
if(screen==='A17')return <><Head subtitle="Review the current inputs and invoice totals."/><Card><div className="steps"><span>1. Rules</span><span>2. Monthly inputs</span><span className="current">3. Preview</span><span>4. Publish</span></div><div className="details"><div><small>Period</small><strong>October 2026</strong></div><div><small>Due date</small><strong>25 October 2026</strong></div><div><small>Eligible invoices</small><strong>1</strong></div><div><small>Exceptions</small><strong>None</strong></div></div><Records columns={['Flat','Maintenance','Water','Sinking fund','Carried dues','Round-off','Total']} rows={[["A-0201","₹2,500","₹350","₹150","₹0","₹0","₹3,000"]]}/><Banner>Changes to inputs require a new preview. Publishing does not notify residents.</Banner><Btn disabled={blocked} onClick={()=>confirm('Publish October invoices?','Create one invoice for ₹3,000, due 25 Oct 2026? Residents will not be notified.',()=>action(()=>{D({published:true});go('A18')},'Invoices published in this simulation.'),'Publish invoices')}>Publish invoices</Btn><Btn secondary onClick={()=>go('A16')}>Back to inputs</Btn></Card></>;
